  const clock = createClock()
  const attempts = []
  const dead = []

  // Queue of {ready, submissionIndex, attempt}
  const queue = submissions.map((_, i) => ({ ready: submissions[i].at, submissionIndex: i, attempt: 1 }))

  // Rate limit tracking
  const startTimes = []
  const limit = policy.limit
  const retry = policy.retry

  while (queue.length > 0) {
    // Find the attempt with smallest ready time, ties break by submission order
    let minIdx = 0
    for (let i = 1; i < queue.length; i++) {
      if (queue[i].ready < queue[minIdx].ready ||
          (queue[i].ready === queue[minIdx].ready && queue[i].submissionIndex < queue[minIdx].submissionIndex)) {
        minIdx = i
      }
    }

    const current = queue.splice(minIdx, 1)[0]
    const submission = submissions[current.submissionIndex]
    const job = jobs.get(submission.id)

    // Advance clock to ready time
    clock.advanceTo(current.ready)

    // Apply rate limit if needed
    if (limit) {
      const window = limit.window
      const cutoff = clock.now() - window

      // Remove starts outside the window
      while (startTimes.length > 0 && startTimes[0] <= cutoff) {
        startTimes.shift()
      }

      // If we're at the limit, advance clock until oldest start leaves the window
      while (startTimes.length >= limit.starts) {
        const newTime = startTimes[0] + window
        clock.advanceTo(newTime)
        // Recalculate cutoff
        const newCutoff = clock.now() - window
        while (startTimes.length > 0 && startTimes[0] <= newCutoff) {
          startTimes.shift()
        }
      }
    }

    const start = clock.now()
    startTimes.push(start)

    // Get the outcome for this attempt
    const outcomes = job.outcomes
    const outcomeIdx = Math.min(current.attempt - 1, outcomes.length - 1)
    const outcome = outcomes[outcomeIdx]

    const finish = start + job.duration
    clock.advanceTo(finish)

    attempts.push({
      start,
      id: submission.id,
      attempt: current.attempt,
      outcome,
      finish,
    })

    // Handle retry or dead letter
    if (outcome === 'fail' && retry) {
      if (current.attempt < retry.max) {
        // Re-queue with backoff
        const backoff = retry.base * Math.pow(2, current.attempt - 1)
        const newReady = finish + backoff
        queue.push({ ready: newReady, submissionIndex: current.submissionIndex, attempt: current.attempt + 1 })
      } else if (current.attempt === retry.max) {
        // Dead letter
        dead.push({
          id: submission.id,
          attempts: current.attempt,
          at: finish,
        })
      }
    }
  }

  return {
    attempts,
    dead,
    end: clock.now(),
  }
}"}

